import {defaults,validateDimensions,buildBrief,restoreDraft} from './project.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const projects=[{id:'walnut',title:'Тёплый минимализм',type:'Кухня',finish:'Орех',layout:'С островом',image:'assets/walnut.jpg',sub:'Орех / светлый камень',description:'Выразительная древесина, спокойные плоскости и остров, вокруг которого собирается дом. Идея для тех, кто любит натуральные оттенки и свободное пространство.',tags:['Орех','Остров','Скрытое хранение']},{id:'sage',title:'Тихая зелень',type:'Кухня',finish:'Шалфей',layout:'Прямая',image:'assets/hero.jpg',sub:'Шалфей / натуральный дуб',description:'Мягкий зелёный, светлое дерево и много дневного света. Спокойное сочетание, которое можно адаптировать под небольшую кухню и повседневные привычки.',tags:['Шалфей','Дуб','Спокойная палитра']},{id:'wardrobe',title:'Всё на своём месте',type:'Гардеробная',finish:'Орех',layout:'Угловая',image:'assets/wardrobe.jpg',sub:'Тёмный дуб / мягкий свет',description:'Открытые секции, удобные ящики и подсветка, которая помогает находить нужное. Отправная точка для системы хранения, где у каждой вещи есть место.',tags:['Хранение','Подсветка','Открытые секции']}];
const colors={'Шалфей':'#9ba58a','Орех':'#806044','Дуб':'#c4a578','Графит':'#464b43','Молочный':'#e9e6d9'};
const layouts={'Кухня':['Прямая','Угловая','П-образная','С островом'],'Шкаф':['Распашной','Купе','Открытый'],'Гардеробная':['Прямая','Угловая','П-образная']};
const symbols={'Прямая':'━','Угловая':'┗','П-образная':'⊓','С островом':'☷','Распашной':'▥','Купе':'▤','Открытый':'▦'};
const DRAFT='batesto-project-v2',FAV='batesto-favorites-v2';
let saved=[];try{const v=JSON.parse(localStorage.getItem(FAV)||'[]');if(Array.isArray(v))saved=v.filter(x=>projects.some(p=>p.id===x));}catch{}
let draft=null;try{draft=restoreDraft(localStorage.getItem(DRAFT));}catch{}
let state=draft||{...defaults,extras:[]};if(!layouts[state.type].includes(state.layout))state.layout=layouts[state.type][0];if(!colors[state.finish])state.finish='Шалфей';state.extras=state.extras.filter(x=>['Подсветка','Выдвижные ящики','Без видимых ручек','Место для техники'].includes(x));
let step=0,view='front',filter='all',currentIdea='walnut',toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function persist(key,value){try{localStorage.setItem(key,value);return true;}catch{toast('Браузер не разрешает сохранение. Скачайте задание файлом.');return false;}}
function renderGallery(){const shown=projects.filter(p=>filter==='all'||p.type===filter);$('#project-grid').classList.toggle('filtered',filter!=='all');$('#project-grid').innerHTML=shown.map(p=>`<article class="project-card"><div class="project-image"><button class="open-project" data-open="${p.id}" aria-label="Открыть ${p.title}"><img src="${p.image}" alt="AI-концепция: ${p.title}" loading="lazy"></button><span class="image-badge">${p.type.toUpperCase()} / КОНЦЕПЦИЯ</span><button class="favorite" data-favorite="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?'Убрать из избранного':'В избранное'}: ${p.title}">${saved.includes(p.id)?'♥':'♡'}</button><span class="image-arrow">↗</span></div><div class="project-info"><div><h3>${p.title}</h3><p>${p.sub}</p></div><span class="project-number">0${projects.indexOf(p)+1}</span></div></article>`).join('');$('#saved-count').textContent=saved.length;}
function openIdea(id){const p=projects.find(p=>p.id===id);if(!p)return;currentIdea=id;$('#detail-image').src=p.image;$('#detail-image').alt='AI-концепция: '+p.title;$('#detail-title').textContent=p.title;$('#detail-description').textContent=p.description;$('#detail-tags').innerHTML=p.tags.map(t=>`<span>${t}</span>`).join('');$('#gallery-dialog').showModal();}
function renderSaved(){$('#saved-list').innerHTML=saved.length?saved.map(id=>{const p=projects.find(x=>x.id===id);return `<article class="saved-item"><button data-saved-open="${id}" aria-label="Открыть ${p.title}"><img src="${p.image}" alt="${p.title}"></button><button data-saved-open="${id}"><h3>${p.title}</h3><p>${p.sub}</p></button><button class="remove-saved" data-remove="${id}" aria-label="Удалить ${p.title}">×</button></article>`;}).join(''):'<div class="empty-saved"><p>Здесь будут ваши любимые идеи.<br>Нажмите на сердце рядом с интерьером.</p><button id="browse-ideas" class="btn">Выбрать настроение ↗</button></div>';}
function toggleSaved(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist(FAV,JSON.stringify(saved));renderGallery();renderSaved();}
$('#project-grid').addEventListener('click',e=>{const open=e.target.closest('[data-open]'),fav=e.target.closest('[data-favorite]');if(open)openIdea(open.dataset.open);if(fav){toggleSaved(fav.dataset.favorite);toast(saved.includes(fav.dataset.favorite)?'Идея добавлена в избранное':'Идея удалена из избранного');}});
$('#saved-open').onclick=()=>{renderSaved();$('#saved-dialog').showModal();};
$('#saved-list').onclick=e=>{const open=e.target.closest('[data-saved-open]'),remove=e.target.closest('[data-remove]');if(open){$('#saved-dialog').close();openIdea(open.dataset.savedOpen);}if(remove)toggleSaved(remove.dataset.remove);if(e.target.closest('#browse-ideas')){$('#saved-dialog').close();$('#collection').scrollIntoView();}};
$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));renderGallery();});
$$('[data-scene]').forEach(b=>b.onclick=()=>{const p=projects.find(x=>x.id===b.dataset.scene);$('#hero-image').src=p.image;$('#hero-image').alt='Концепция интерьера: '+p.title;$('#scene-number').textContent=`0${projects.indexOf(p)+1} / 03`;$('#scene-title').textContent=p.title;$$('[data-scene]').forEach(x=>x.setAttribute('aria-pressed',x===b));});
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('.menu-toggle').onclick=()=>{const open=$('.header nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);};$$('.header nav a').forEach(a=>a.onclick=()=>{$('.header nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');});
function renderOptions(){$('#type-options').innerHTML=Object.keys(layouts).map(t=>`<button type="button" data-type="${t}" aria-pressed="${state.type===t}">${t}</button>`).join('');$('#layout-options').innerHTML=layouts[state.type].map(l=>`<button type="button" data-layout="${l}" aria-pressed="${state.layout===l}"><span class="layout-symbol" aria-hidden="true">${symbols[l]}</span>${l}</button>`).join('');$('#finish-options').innerHTML=Object.entries(colors).map(([n,c])=>`<button type="button" data-finish="${n}" aria-pressed="${state.finish===n}"><i style="background:${c}"></i>${n}</button>`).join('');}
function fillFields(){for(const key of ['width','height','depth','name','city','notes','budget'])$('#'+key).value=state[key];$$('.extra-options input').forEach(x=>x.checked=state.extras.includes(x.value));}
function readFields(){for(const key of ['width','height','depth','name','city','notes','budget'])state[key]=$('#'+key).value;state.extras=$$('.extra-options input:checked').map(x=>x.value);}
function markChanged(){$('#draft-status').textContent='Есть несохранённые изменения';}
function setStep(next,focus=false){step=next;$('#project-form').hidden=false;$('#result').hidden=true;$$('.wizard-page').forEach(p=>p.hidden=Number(p.dataset.step)!==step);$$('.wizard-steps li').forEach((l,i)=>{l.classList.toggle('active',i===step);if(i===step)l.setAttribute('aria-current','step');else l.removeAttribute('aria-current');});$('#back-step').hidden=step===0;$('#step-help').hidden=step!==0;$('#next-step').innerHTML=step===3?'Собрать задание <span>↗</span>':'Дальше <span>→</span>';if(focus){const title=$(`.wizard-page[data-step="${step}"] h3`);title.tabIndex=-1;title.focus({preventScroll:true});if(window.innerWidth<801)title.scrollIntoView({block:'start'});}}
function draw(){const p={...state};for(const k of ['width','height','depth'])p[k]=Math.min({width:10000,height:3500,depth:1200}[k],Math.max({width:600,height:500,depth:200}[k],Number(p[k])||defaults[k]));const w=Math.min(420,p.width/8),h=Math.min(230,p.height/11),x=(560-w)/2,y=300-h,c=colors[p.finish];let s='<defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M 20 0 L 0 0 0 20" fill="none" stroke="#cbd3be" stroke-width=".4"/></pattern><pattern id="grain" width="9" height="20" patternUnits="userSpaceOnUse"><path d="M3 0V20 M7 0V20" stroke="#ffffff" opacity=".06"/></pattern></defs><rect x="20" y="35" width="520" height="290" fill="url(#grid)"/>';
const rect=(a,b,ww,hh,fill=c)=>`<rect x="${a}" y="${b}" width="${ww}" height="${hh}" fill="${fill}" stroke="#505b41" stroke-width="1"/>`;
const line=(a,b,aa,bb,color='#859174')=>`<line x1="${a}" y1="${b}" x2="${aa}" y2="${bb}" stroke="${color}"/>`;
const dim=(xx,yy,ww,txt)=>line(xx,yy,xx+ww,yy)+line(xx,yy-5,xx,yy+5)+line(xx+ww,yy-5,xx+ww,yy+5)+`<text x="${xx+ww/2}" y="${yy-9}" text-anchor="middle">${txt} мм</text>`;
if(view==='plan'){const d=Math.max(34,Math.min(95,p.depth/10));const py=140;s+=rect(x,py,w,d);if(['Угловая','П-образная'].includes(p.layout))s+=rect(x,py+d,d,105);if(p.layout==='П-образная')s+=rect(x+w-d,py+d,d,105);if(p.layout==='С островом')s+=rect(x+w*.25,py+d+40,w*.5,50,'#d3cfbd');for(let i=1;i<Math.max(2,Math.round(p.width/600));i++)s+=line(x+w*i/Math.max(2,Math.round(p.width/600)),py,x+w*i/Math.max(2,Math.round(p.width/600)),py+d);s+=dim(x,100,w,p.width);s+=`<text x="280" y="355" text-anchor="middle">Глубина модулей · ${p.depth} мм</text>`;}
else {s+=line(40,304,520,304);const n=Math.max(2,Math.min(10,Math.round(p.width/600))),mw=w/n;if(p.type==='Кухня'){const lower=h*.39,upper=h*.32;for(let i=0;i<n;i++){s+=rect(x+i*mw,300-lower,mw,lower);if(i!==Math.floor(n*.55))s+=rect(x+i*mw,y,mw,upper);if(!p.extras.includes('Без видимых ручек'))s+=line(x+i*mw+mw*.65,300-lower+10,x+i*mw+mw*.85,300-lower+10,'#35422a');if(p.extras.includes('Выдвижные ящики')&&i===0){s+=line(x,300-lower*.66,x+mw,300-lower*.66);s+=line(x,300-lower*.33,x+mw,300-lower*.33);}}
s+=rect(x-3,297-lower,w+6,5,'#d5d0bd');if(p.extras.includes('Место для техники'))s+=rect(x+mw,300-lower+8,mw,lower-15,'#343e2c');if(p.extras.includes('Подсветка'))s+=`<rect x="${x}" y="${y+upper+3}" width="${w}" height="3" fill="#e9bc60"/>`;if(p.layout==='С островом')s+=rect(x+w*.2,280,w*.6,40,'#b7ad90');}
else{for(let i=0;i<n;i++){s+=rect(x+i*mw,y,mw,h);const open=p.type==='Гардеробная'||p.layout==='Открытый';if(open){s+=rect(x+i*mw+5,y+6,mw-10,h-12,'#70664c');for(let j=1;j<4;j++)s+=line(x+i*mw+5,y+h*j/4,x+(i+1)*mw-5,y+h*j/4,'#c2b08c');if(p.extras.includes('Подсветка'))s+=line(x+i*mw+8,y+8,x+i*mw+8,y+h-8,'#e8c578');}else if(!p.extras.includes('Без видимых ручек'))s+=line(x+(i+1)*mw-8,y+h*.4,x+(i+1)*mw-8,y+h*.6,'#323e29');if(p.extras.includes('Выдвижные ящики'))s+=rect(x+i*mw+5,y+h*.75,mw-10,h*.22);}}
s+=dim(x,y-20,w,p.width);s+=`<text x="${Math.max(18,x-18)}" y="${y+h/2}" text-anchor="middle" transform="rotate(-90 ${Math.max(18,x-18)} ${y+h/2})">${p.height} мм</text>`;if(['Орех','Дуб'].includes(p.finish))s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#grain)" pointer-events="none"/>`;s+=`<text x="280" y="352" text-anchor="middle">${p.layout} · общий вид фасадов</text>`;}
$('#drawing').innerHTML=s;$('#preview-title').textContent=`${state.type} / ${state.layout}`;$('#preview-spec').textContent=`${state.width||'—'} × ${state.height||'—'} × ${state.depth||'—'} мм`;}
$('#type-options').onclick=e=>{const b=e.target.closest('[data-type]');if(!b)return;state.type=b.dataset.type;state.layout=layouts[state.type][0];renderOptions();draw();markChanged();};$('#layout-options').onclick=e=>{const b=e.target.closest('[data-layout]');if(!b)return;state.layout=b.dataset.layout;renderOptions();draw();markChanged();};$('#finish-options').onclick=e=>{const b=e.target.closest('[data-finish]');if(!b)return;state.finish=b.dataset.finish;renderOptions();draw();markChanged();};
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.setAttribute('aria-pressed',x===b));draw();});
$('#project-form').addEventListener('input',()=>{readFields();draw();markChanged();});
$('#project-form').onsubmit=e=>{e.preventDefault();readFields();if(step===1){const error=validateDimensions(state);$('#dimension-error').textContent=error;if(error){$('#width').focus();return;}}if(step<3){setStep(step+1,true);return;}if(!state.name.trim()||!state.city.trim()){$('#contact-error').textContent='Укажите имя и город, чтобы мастер понимал, к кому обращаться и где нужен проект.';(!state.name.trim()?$('#name'):$('#city')).focus();return;}$('#contact-error').textContent='';$('#brief-output').value=buildBrief(state);$('#project-form').hidden=true;$('#result').hidden=false;$('#result h3').tabIndex=-1;$('#result h3').focus({preventScroll:true});if(window.innerWidth<801)$('#result').scrollIntoView();};
$('#back-step').onclick=()=>setStep(Math.max(0,step-1),true);$('#edit-project').onclick=()=>setStep(3,true);
$('#save-draft').onclick=()=>{readFields();const err=validateDimensions(state);if(err){setStep(1,true);$('#dimension-error').textContent=err;return;}if(persist(DRAFT,JSON.stringify({version:2,project:state}))){$('#draft-status').textContent='Сохранено в браузере';toast('Проект сохранён. Можно вернуться позже.');}};
function reset(){state={...defaults,extras:[]};fillFields();renderOptions();draw();setStep(0);$('#dimension-error').textContent='';$('#contact-error').textContent='';$('#draft-status').textContent='Новый проект';try{localStorage.removeItem(DRAFT);}catch{}}
$('#reset-project').onclick=()=>{reset();toast('Начат новый проект');};
$('#use-idea').onclick=()=>{const p=projects.find(x=>x.id===currentIdea);state.type=p.type;state.layout=p.layout;state.finish=p.finish;if(p.id==='wardrobe')state.extras=[...new Set([...state.extras,'Подсветка'])];renderOptions();fillFields();draw();setStep(0);markChanged();$('#gallery-dialog').close();$('#configurator').scrollIntoView();toast('Идея выбрана. Настройте проект под себя.');};
$('#copy-brief').onclick=async()=>{try{await navigator.clipboard.writeText($('#brief-output').value);$('#result-status').textContent='Задание скопировано. Откройте чат с Вадимом и вставьте текст.';}catch{$('#brief-output').focus();$('#brief-output').select();$('#result-status').textContent='Текст выделен. Нажмите Ctrl+C или выберите «Копировать».';}};
$('#download-brief').onclick=()=>{const blob=new Blob(['\uFEFF'+$('#brief-output').value],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Batesto — мой проект.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#result-status').textContent='Задание подготовлено для скачивания.';};
$('#privacy-open').onclick=()=>$('#privacy-dialog').showModal();$('#clear-local').onclick=()=>{try{localStorage.removeItem(DRAFT);localStorage.removeItem(FAV);}catch{}saved=[];reset();renderGallery();$('#privacy-dialog').close();toast('Сохранённый проект и избранное удалены');};
renderGallery();renderOptions();fillFields();draw();setStep(0);if(draft)$('#draft-status').textContent='Восстановлен сохранённый проект';
